-- ---- M381E-01 Anmeldung und Verfahrenswahl (4) ----

-- thickening_principle
update public.fields set verification_status='verified_against_standard', verification_quote='For decades thickening of sewage sludge has been accomplished by using either gravity settling in thickeners or in a flotation unit or by mechanical thickening. | Thickening devices which make use of natural gravitational forces are rotary drum screens, screw thickeners, gravity belt thickeners, disk thickeners and thickening pumps. — printed p.3 and p.20', verification_note='md-verified 2026-09-05 (Foreword + §4.2.1, printed p.3 and p.20) [VC] — the four encoded families map to §4.1 gravity (p.13), §4.1.3 flotation (p.17), §4.2 mechanical/natural gravity (p.20) and §4.3 mechanical/artificial gravity = centrifuges (p.25).', verified_at=now() where id='8d2e62c7-81bb-4541-9226-11c09651bbc0' and verification_status not in ('verified_against_standard','corrected');

-- sludge_type
update public.fields set verification_status='verified_against_standard', verification_quote='Table 1: Dimensioning parameters for continuous-flow gravity thickeners | hardly settleable & waste activated sludge & 20-50 | averagely settleable & mixed primary sludge, digested sludge & 40-80 | easily settleable & primary sludge, mineral sludges, non-digestible sludges & up to 100 | Non-stabilised sludge (DIN EN 1085 [2]) — printed p.16 and p.7', verification_note='md-verified 2026-09-05 (§4.1.2 Tab.1 + §2.1.4, printed p.16 and p.7) [VC] — Tab.1 names primary / mixed primary / waste activated / digested sludge; the 5th enum value "raw" is defined in §2.1.4 but carries NO printed SLR row in Tab.1. Staged.', verified_at=now() where id='36b32748-c4ad-4347-9718-7c0fd4992462' and verification_status not in ('verified_against_standard','corrected');

-- application_purpose
update public.fields set verification_status='verified_against_standard', verification_quote='The primary objective of sludge thickening is the reduction of the volume of the produced sewage sludge. As secondary objective, this volume reduction has positive effects on the following treatment steps since treatment processes are stabilised. Volume reduction enables optimisation of construction and operating costs. — printed p.10', verification_note='md-verified 2026-09-05 (§3, printed p.10) [VC]', verified_at=now() where id='90f4d38e-0863-4e1a-b04b-80a90d9a6c12' and verification_status not in ('verified_against_standard','corrected');

-- other_sludge_applicability
update public.fields set verification_status='verified_against_standard', verification_quote='Information and recommendations of this Advisory Leaflet, however, to a large extent can be used accordingly for the treatment of other sludges, e.g. sludges produced during drinking water treatment (see [20]) or during industrial wastewater treatment. Then it is above all the responsibility of the user to verify transferability of given recommendations in regard to special characteristics of each individual sludge and in regard to impacts on dimensioning and operation of the plant. — printed p.6', verification_note='md-verified 2026-09-05 (§1 Scope, printed p.6) [VC]', verified_at=now() where id='ebbaef43-0969-44fb-81be-c3b95971379c' and verification_status not in ('verified_against_standard','corrected');

