update public.fields set verification_status='verified_against_standard', verification_quote='Abbreviations and Symbols | SVI & ISV & $\mathrm{ml} / \mathrm{g}$ or 1/kg & Sludge volume index — printed p.9', verification_note='md-verified 2026-09-05 (§2.2 symbol table, printed p.9) [VC] — the guideline declares this symbol in TWO units ("ml/g or 1/kg"); the encoded unit ml/g is the first of the two and the two are numerically identical (1 ml/g = 1 l/kg). Definition only; the leaflet states no SVI limit.', verified_at=now() where id='4079b56a-3264-4281-8f28-df7ba5f6268e' and verification_status not in ('verified_against_standard','corrected');

