update public.fields set verification_status='verified_against_standard', verification_quote='Thickening devices which make use of natural gravitational forces are rotary drum screens, screw thickeners, gravity belt thickeners, disk thickeners and thickening pumps. — printed p.20', verification_note='md-verified 2026-09-05 (§4.2.1/§4.2.2, printed p.20) [VC] — the five encoded enum values are exactly the five printed device types (§4.2.2.1-§4.2.2.5, p.21-24).', verified_at=now() where id='0f2f8474-5a1b-418c-a5ea-3ea9a4da64ad' and verification_status not in ('verified_against_standard','corrected');

-- machine_capacity
update public.fields set verification_status='verified_against_standard', verification_quote='Table 3: Manufactured sizes of rotary drum screens | Capacity & $\mathrm{m}^{3} / \mathrm{h}$ & 3 & 100 | Table 4: Manufactured sizes of rotary screw thickeners | Capacity & $\mathrm{m}^{3} / \mathrm{h}$ & 8 & 90 | Table 5: Manufactured sizes of belt thickeners | Capacity & $\mathrm{m}^{3} / \mathrm{h}$ & 10 & 150 | Table 6: Manufactured sizes of disk thickeners | Capacity & $\mathrm{m}^{3} / \mathrm{h}$ & 5 & 40 | Table 7: Manufactured sizes of thickening pumps | Capacity & $\mathrm{m}^{3} / \mathrm{h}$ & 2 & 15 — printed p.21, p.23 and p.24', verification_note='md-verified 2026-09-05 (§4.2.2 Tab.3-Tab.7, printed p.21, p.23, p.24) [VC] — all five encoded ranges match the print. These are MANUFACTURED sizes (market availability), not requirements; correctly NOT gated. The encoding holds all five in one field with no machine-type scoping, so the effective admissible band is the union 2-150 m3/h. Staged.', verified_at=now() where id='7b78d75b-e046-4ff0-93dd-4c2bb62490c8' and verification_status not in ('verified_against_standard','corrected');

-- solids_feed_capacity
update public.fields set verification_status='verified_against_standard', verification_quote='Table 3: Manufactured sizes of rotary drum screens | Solids feed capacity & kg/h & 15 & 1500 | Solids capacity & kg/h & 40 & 750 | Solids feed capacity & $\mathrm{kg} / \mathrm{h}$ & 50 & 2250 | Solids feed capacity & kg/h & 25 & 350 | Solids feed capacity & $\mathrm{kg} / \mathrm{h}$ & 20 & 150 — printed p.21, p.23 and p.24', verification_note='md-verified 2026-09-05 (§4.2.2 Tab.3-Tab.7, printed p.21, p.23, p.24) [VC] — rows quoted in Tab.3/4/5/6/7 order (drum 15-1500, screw 40-750, belt 50-2250, disk 25-350, pump 20-150 kg/h); all match the encoding. Tab.4 labels the same quantity "Solids capacity" (no "feed"), quoted verbatim. Manufactured sizes, not requirements; not gated.', verified_at=now() where id='686d2598-04b5-4315-8e2e-c1b71f595a68' and verification_status not in ('verified_against_standard','corrected');

