update public.fields set verification_status='verified_against_standard', verification_quote='Various manufacturers of centrifuges also offer cocurrent as well as counter-current centrifuges for the thickening of waste activated sludge. The difference lies in the location of the feed point in the centrifuge and in the direction of flow of the sludge phase and the liquid phase. In operation, generally no significant differences of efficiency can be observed. — printed p.25', verification_note='md-verified 2026-09-05 (§4.3.1, printed p.25) [VC] — the two encoded enum values are the two printed designs; the print explicitly states no efficiency difference, so no gate is defensible and none exists.', verified_at=now() where id='8869d63a-c3ac-46ec-9b6e-f5e91bcf2493' and verification_status not in ('verified_against_standard','corrected');

