-- ---- M381E-07 Konditionierung / Polymerdosierung (6) ----

-- specific_flocculant_demand
update public.fields set verification_status='verified_against_standard', verification_quote='Table 9: Total solids content in the discharge [\% TS], spec. flocculant demand and spec. energy demand of various thickening processes | Specific flocculant demand & [kg AS/MgTSS] & 0 & 0,5-3 & 0 & 0 & 3-7 & 0 & 1-1.5 — printed p.28', verification_note='md-verified 2026-09-05 (§5.2 Tab.9, printed p.28) [VC] — column order is gravity continuous (2 columns) / batch / dissolved air flotation / mechanical / centrifuge without / centrifuge with flocculant; each encoded cell matches. Note the last cell prints "1-1.5" with a DOT although §2.2 states "A comma is used as a decimal sign". Tab.9 gives expectations ("the following mean results ... can be expected"), not requirements; gate CR-019 is presence-only on this field and is anchored on a §5.3 "is recommended" sentence. Staged.', verified_at=now() where id='0bf991c7-4b16-4370-a626-b1b717bd4ec9' and verification_status not in ('verified_against_standard','corrected');

-- flocculant_product_type
update public.fields set verification_status='verified_against_standard', verification_quote='Generally, a crosslinked liquid flocculant or a mixture of liquid and solid flocculants is used for conditioning. | In contrast to thickening aggregates which use natural gravity, centrifuges require a very low specific flocculant quantity for conditioning. Inexpensive powder flocculants can be used as well. | Polyacrylamide PAM is the main component of polymers (organic flocculants) used for sludge conditioning. — printed p.20, p.25 and p.32', verification_note='md-verified 2026-09-05 (§4.2.1 + §4.3.1 + §6.3, printed p.20, p.25 and p.32) [VC] — the fourth enum value "none" (no conditioning) is supported by Tab.9 (§5.2, p.28), whose flocculant-demand row prints 0 for gravity batch, flotation and centrifuge-without-flocculant.', verified_at=now() where id='6e953094-b6c1-43dc-9666-9fcceffbfff9' and verification_status not in ('verified_against_standard','corrected');

-- polymer_active_substance
update public.fields set verification_status='verified_against_standard', verification_quote='The specific flocculant demand for thickening of waste activated sludge given in Table 9 is related to the poly-mer-active substance (AS) of an accordingly prepared solution with a specific concentration. The polymeractive substance (polymer content) specifies the polymeric fraction of the product. — printed p.27-28', verification_note='md-verified 2026-09-05 (§5.2, printed p.27-28) [VC] — the transcript carries the hyphenation artefacts "poly-mer-active" and "polymeractive" from the printed line breaks; quoted verbatim.', verified_at=now() where id='e4cdb704-915b-4af7-ae5e-ee32e3b4c840' and verification_status not in ('verified_against_standard','corrected');

-- reuse_pathway
update public.fields set verification_status='verified_against_standard', verification_quote='According to the ordinance, if sludge is to be reused in agriculture, then PAM shall neither be used in wastewater treatment (e. g. to prevent uncontrolled sludge discharge from the secondary settling tank) nor for thickening and dewatering in sludge treatment. For sludge incineration, no restrictions for polymer conditioning are known at the moment [19]. — printed p.32', verification_note='md-verified 2026-09-05 (§6.3, printed p.32) [VC] — the two encoded enum values are exactly the two printed pathways. GATE FINDING: CR-013 is written as the conjunction "reuse_pathway == agricultural AND pam_used == false", so the printed implication (agricultural => no PAM) becomes a demand that EVERY project be agricultural, and the printed case "For sludge incineration, no restrictions ... are known" is unsatisfiable. Staged.', verified_at=now() where id='1baf7227-bc46-4454-bb33-3f9e4e612e61' and verification_status not in ('verified_against_standard','corrected');

-- pam_used
update public.fields set verification_status='verified_against_standard', verification_quote='According to § 2 and § 3 of the $D \ddot{u} M V$, fertilizer types are registered under the requirement that "no polyacrylamides (PAM) or mineral oils are used as conditioning agent in production and that no increased pollutant concentrations are caused by the use of other conditioning agents". — printed p.32', verification_note='md-verified 2026-09-05 (§6.3, printed p.32) [VC] — NR-flavoured: the binding text is the German DueMV (26 November 2003) quoted by the leaflet, not the leaflet itself; the leaflet also prints a PAM transition period ending 4 December 2013, which has since lapsed. The governing ordinance is not in the library, so this caps at VC/NR.', verified_at=now() where id='0d1814ec-fb75-4bc2-9398-8be8b8929714' and verification_status not in ('verified_against_standard','corrected');

-- conditioner_fraction
update public.fields set verification_status='verified_against_standard', verification_quote='In addition, it shall be noted, that Annex 3 regulates the labelling of fertilizers which are not classified as EC-fertilizers, i.e. if a conditioning agent for fertilizer production exceeds a percentage of $0,5 \%$, it shall be declared separately. — printed p.32', verification_note='md-verified 2026-09-05 (§6.3, printed p.32) [VC] — the printed 0,5 % is a DECLARATION threshold, not a cap. GATE FINDING: CR-014 (conditioner_fraction <= 0.5) blocks above the threshold, i.e. it invents a limit where the source only obliges a declaration to be made. Staged block -> warn + attestation.', verified_at=now() where id='49152b63-82e9-4267-afbe-c4749acaa893' and verification_status not in ('verified_against_standard','corrected');

