update public.fields set verification_status='verified_against_standard', verification_quote='Calculation of the solids-related degree of separation: | $T S S_{\text {Dis }}$ & {$[\mathrm{gTSS} / \mathrm{l}]$} & Solids content of sludge discharge — printed p.7-8', verification_note='md-verified 2026-09-05 (§2.1.10 Eq.1 legend, printed p.7-8) [VC] — unit gTSS/l matches the print.', verified_at=now() where id='c82ea18a-3e7c-4e0d-890c-2813defaccf1' and verification_status not in ('verified_against_standard','corrected');

-- eta
update public.fields set verification_status='verified_against_standard', verification_quote='Ratio of mass separated in a separation process to the introduced mass of a substance (DIN EN 1085 [2]). | The solids-related degree of separation of the various processes generally lies between ca. $92 \%$ and $96 \%$ in dependency on sludge characteristics, degree of thickening, and specific flocculant quantities. Only for the operation of thickening centrifuges without the addition of flocculants, a degree of separation between $85 \%$ and $92 \%$ is to be expected | A degree of separation between $85 \%$ and $90 \%$ should be realised — printed p.7, p.28 and p.31', verification_note='md-verified 2026-09-05 (§2.1.10 + §5.2 + §6.2, printed p.7, p.28 and p.31) [VC] — output of Eq.1. THREE gate findings on this one field: (1) CR-012 (eta >= 92 AND eta <= 96) is built on the descriptive band "generally lies between ca. 92 % and 96 %" and makes the OTHER printed case, 85-92 % for centrifuges without flocculant, unreachable — and blocks any result better than 96 %; (2) CR-011 (eta >= 85) is a strict subset of CR-012 and rests on a "should"; (3) CR-010 (eta IS NOT NULL) is a strict subset of both. Staged.', verified_at=now() where id='78c6a10b-cfa8-451a-b24a-5def129b268d' and verification_status not in ('verified_against_standard','corrected');

-- discharge_TS
update public.fields set verification_status='verified_against_standard', verification_quote='Table 9: Total solids content in the discharge [\% TS], spec. flocculant demand and spec. energy demand of various thickening processes | Primary sludge & [\% TS] & 5-10 & - & 5-10 & - & - & - & - | Mixed primary sludge & [\% TS] & 4-6 & 5-8 & 4-8 & - & - & - & - | Waste activated sludge & [\% TS] & 2-3 & 3-4 & 2-3 & 3-5 & 5-7 & 5-7 & 6-8 — printed p.28', verification_note='md-verified 2026-09-05 (§5.2 Tab.9, printed p.28) [VC] — SR-2: a per-process/per-sludge-type range table, so any point value stays an engineer selection. FINDING: the encoded description compresses printed cells into unions the guideline never prints — "gravity 2-4" unions the two printed gravity-continuous cells 2-3 and 3-4, "centrifuge 5-8" unions 5-7 and 6-8. Staged (description only; no gate is built on this field).', verified_at=now() where id='9410f6a1-4969-43eb-9c04-466af76c2845' and verification_status not in ('verified_against_standard','corrected');

-- specific_energy_demand_vol
update public.fields set verification_status='verified_against_standard', verification_quote='Table 9: Total solids content in the discharge [\% TS], spec. flocculant demand and spec. energy demand of various thickening processes | Specific. energy demand & [ $\mathrm{kWh} / \mathrm{m}^{3}$ ] & < 0,1 & < 0,1 & - & 0,6-1,2 & < 0,2 & 1-1,4 & 0,6-1 — printed p.28', verification_note='md-verified 2026-09-05 (§5.2 Tab.9, printed p.28) [VC] — the encoded description states "centrifuge 0,6-1,4", which unions the two printed centrifuge cells 1-1,4 (without flocculant) and 0,6-1 (with flocculant). Staged. Not gated.', verified_at=now() where id='4cc962d2-5db7-4fcd-aab2-a433bdad69c5' and verification_status not in ('verified_against_standard','corrected');

-- specific_energy_demand_mass
update public.fields set verification_status='verified_against_standard', verification_quote='Table 9: Total solids content in the discharge [\% TS], spec. flocculant demand and spec. energy demand of various thickening processes | Specific. energy demand & [kWh/MgTSS] & < 20 & < 20 & - & 100-140 & < 30 & 180 220 & 100 140 — printed p.28', verification_note='md-verified 2026-09-05 (§5.2 Tab.9, printed p.28) [VC] — TRANSCRIPT DEFECT: the last two cells lose their range dash in the md and read "180 220" and "100 140"; by analogy with the volumetric row they are 180-220 and 100-140 kWh/MgTSS. The encoded description states "centrifuge 100-220", a union of those two cells. Staged; PDF confirmation owed for the two dashes.', verified_at=now() where id='a548c655-cb45-4e2e-ae31-b6baee1333a5' and verification_status not in ('verified_against_standard','corrected');

-- ---- M381E-09 Auswirkungen auf Behandlungskette und Trubwasser (3) ----

-- hydraulic_return_load
update public.fields set verification_status='verified_against_standard', verification_quote='The higher the degree of thickening, the larger the recycled fraction of sludge liquor will be and in turn the hydraulic return load. However, it only amounts to ca. $1 \%$ of wastewater influent [13] to the treatment plant and thus only adds marginal hydraulic load. — printed p.31', verification_note='md-verified 2026-09-05 (§6.2, printed p.31) [VC] — descriptive magnitude ("ca. 1 %"), not a limit; correctly NOT gated.', verified_at=now() where id='c54c181c-9673-4749-9531-8858c77e444c' and verification_status not in ('verified_against_standard','corrected');

-- sludge_liquor_destination
update public.fields set verification_status='verified_against_standard', verification_quote='Solids contained in the centrate/filtrate in general are easily settleable. Therefore it makes sense to feed the sludge liquor from thickening processes to the wastewater treatment plant influent or to the influent of the primary sedimentation tank. | For mechanical thickening with a sufficiently high degree of separation and an accordingly low concentration of solids in the filtrate/centrate, a direct recycling of the sludge liquor to the wastewater treatment plant influent is recommended. — printed p.31 and p.32', verification_note='md-verified 2026-09-05 (§6.2 + §6.4, printed p.31 and p.32) [VC] — free text; the modal is "it makes sense" / "is recommended", so no block gate would be defensible and none exists.', verified_at=now() where id='c1203470-528d-41f8-839e-3a52c2c80605' and verification_status not in ('verified_against_standard','corrected');

-- separate_liquor_treatment
update public.fields set verification_status='verified_against_standard', verification_quote='A separate treatment of sludge liquor from the thickening process is only necessary if partial degradation or conversion or extensive hydrolysis of organic substances takes place during the thickening process. This is the case e.g. for disintegration. — printed p.32', verification_note='md-verified 2026-09-05 (§6.4, printed p.32) [VC] — GATE FINDING: CR-020 is written "separate_liquor_treatment IN {true,false}", which is a no-op for a boolean field (it can only be true, false or NULL) and uses brace syntax the condition grammar does not parse. Staged.', verified_at=now() where id='d708bd9b-0ff3-421f-8be1-8ed759229d70' and verification_status not in ('verified_against_standard','corrected');

-- ---- M381E-10 Kosten und Wirtschaftlichkeitsvergleich (9) ----

-- energy_cost
update public.fields set verification_status='verified_against_standard', verification_quote='Table 10: Cost factors for comparing economic efficiency | COSTS FOR UTILITIES AND SUPPLIES | Energy costs & € / kWh — printed p.33', verification_note='md-verified 2026-09-05 (§7 Tab.10, printed p.33) [VC] — Tab.10 lists the cost FACTORS to be taken into account; it prints no values, so every cost field on this worksheet is engineer_input by construction.', verified_at=now() where id='6d57e4f2-de17-4cd3-9b78-49ad7ee44abc' and verification_status not in ('verified_against_standard','corrected');

