-- i
update public.fields set verification_status='verified_against_standard', verification_quote='Investment costs were converted to annual costs using the equivalent annuity method and the capital recovery factor CRF | \mathrm{CRF}=\frac{i \cdot(1+i)^{\mathrm{n}}}{(1+i)^{\mathrm{n}}-1} \tag{4} — printed p.33', verification_note='md-verified 2026-09-05 (§7 Eq.4, printed p.33) [VC] — i is the interest rate as the dimensionless factor Eq.4 consumes; see the interest_rate duplicate finding.', verified_at=now() where id='c721bc08-4d36-494b-975b-b717862207d8' and verification_status not in ('verified_against_standard','corrected');

