update public.fields set verification_status='verified_against_standard', verification_quote='Table 10: Cost factors for comparing economic efficiency | UTILISATION PERIOD & | Mechanical and electrical engineering n & years | Structural engineering n & years — printed p.33', verification_note='md-verified 2026-09-05 (§7 Tab.10 + Eq.4, printed p.33) [VC] — Tab.10 prints TWO utilisation periods (mechanical/electrical and structural), each with its own CRF; the encoding holds a single n and a single CRF, so only one of the two annuities can be represented. Staged.', verified_at=now() where id='122a7f47-90df-4285-ba43-6b823cce4b36' and verification_status not in ('verified_against_standard','corrected');

-- CRF
update public.fields set verification_status='verified_against_standard', verification_quote='Table 10: Cost factors for comparing economic efficiency | CAPITAL RECOVERY FACTOR & | Mechanical and electrical engineering CRF & factor | Structural engineering CRF & factor — printed p.33', verification_note='md-verified 2026-09-05 (§7 Tab.10 + Eq.4, printed p.33) [VC] — output of Eq.4. ORPHAN FINDING: nothing consumes CRF — no equation multiplies investment_cost by CRF and no gate reads it, so the computed annuity factor is never applied downstream and the annual-cost comparison Tab.10/Fig.15 describes is never assembled. Staged.', verified_at=now() where id='51a37041-4d48-4ebb-b7b4-81d618fb5f21' and verification_status not in ('verified_against_standard','corrected');

