-- labour_cost
update public.fields set verification_status='verified_against_standard', verification_quote='Table 10: Cost factors for comparing economic efficiency | LABOUR COSTS & | Labour costs (annual) & € / (per capita ⋅ a) — printed p.33', verification_note='md-verified 2026-09-05 (§7 Tab.10, printed p.33) [VC] — the printed unit is € per capita and year; the encoded unit EUR/(E.a) uses the leaflet symbol I/E for inhabitant (§2.2, p.9). Consistent.', verified_at=now() where id='e82653e9-b05e-4d7c-8c19-6ef9dae43625' and verification_status not in ('verified_against_standard','corrected');

